    .replace(/\{\{conhecimento\}\}/gi, vars.conhecimento?.trim() || 'Nenhum trecho indexado.')
    .replace(/\{\{checklist_verificacao\}\}/gi, vars.checklistVerificacao?.trim() || 'Checklist padrão Cortecloud.')
